using System;using System.Drawing;using System.IO;using System.Threading;using System.Threading.Tasks;using System.Windows.Forms;
namespace Captura {
 static class RecordingTests {
  public static void Run(){string directory=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"recording-tests-"+DateTime.Now.ToString("yyyyMMdd-HHmmss"));Directory.CreateDirectory(directory);using(var fixture=new Form{Text="Priint TEST FIXTURE",StartPosition=FormStartPosition.Manual,Location=new Point(80,80),ClientSize=new Size(640,360),BackColor=Color.Navy,ShowInTaskbar=false}){fixture.Controls.Add(new Label{Text="PRIINT RECORDING TEST",Font=new Font("Segoe UI",24),ForeColor=Color.Lime,AutoSize=true,Location=new Point(30,30)});fixture.Shown+=async delegate{try{IntPtr hwnd=fixture.Handle;string ff=EncoderLocator.Find();if(ff==null)throw new Exception("FFmpeg ausente");Rectangle area=new Rectangle(fixture.Left+10,fixture.Top+40,320,180);await Task.Run(async delegate{
   Rectangle desktop=new Rectangle(-1920,0,3840,1080);var follow=new RecordingRequest{Mode=RecordingMode.Region,Region=new Rectangle(0,0,640,360),FollowMouse=true,FollowSize=new Size(640,360)};Rectangle left=RecordingEngine.ComputeArea(follow,desktop,new Point(-1900,10),Rectangle.Empty),right=RecordingEngine.ComputeArea(follow,desktop,new Point(1900,1070),Rectangle.Empty);if(!desktop.Contains(left)||!desktop.Contains(right)||left.X==right.X)throw new Exception("Geometria follow falhou");
      using(var retry=new RecordingEngine()){
    bool rejected=false;try{retry.Start(new RecordingRequest{Mode=RecordingMode.Window,WindowHandle=IntPtr.Zero,EncoderPath=ff,OutputDirectory=directory});}catch{rejected=true;}if(!rejected||retry.IsRecording)throw new Exception("Janela inválida não rejeitada");
    rejected=false;try{retry.Start(new RecordingRequest{Mode=RecordingMode.Region,Region=area,CameraDevice="dummy",CameraBounds=new Rectangle(0,0,100,80),EncoderPath=ff,OutputDirectory=directory});}catch{rejected=true;}if(!rejected||retry.IsRecording)throw new Exception("Câmera em área não rejeitada");
    retry.Start(new RecordingRequest{Mode=RecordingMode.Region,Region=area,Fps=30,EncoderPath=ff,OutputDirectory=directory});await Task.Delay(600);string recovered=await retry.StopAsync();if(!File.Exists(recovered))throw new Exception("Recuperação após erro falhou");File.AppendAllText(Path.Combine(directory,"recovery.txt"),"OK: janela inválida, câmera em área rejeitadas, retomada válida.");
   }
   foreach(string test in new[]{"region","monitor","window","desktop","follow","camera","nvenc"}){var req=new RecordingRequest{Mode=test=="window"?RecordingMode.Window:test=="desktop"?RecordingMode.Desktop:test=="monitor"||test=="camera"?RecordingMode.Monitor:RecordingMode.Region,Region=area,WindowHandle=hwnd,OutputDirectory=directory,Fps=30,CaptureCursor=true,FollowMouse=test=="follow",FollowSize=area.Size,EncoderPath=ff,UseNvenc=test=="nvenc",TestCamera=test=="camera",CameraBounds=new Rectangle(200,90,100,76)};using(var recorder=new RecordingEngine()){string failure=null;recorder.Failed+=s=>failure=s;recorder.Start(req);await Task.Delay(1800);string result=await recorder.StopAsync();if(failure!=null||string.IsNullOrEmpty(result)||!File.Exists(result))throw new Exception(test+": "+failure);File.AppendAllText(Path.Combine(directory,"results.txt"),test+" OK "+Path.GetFileName(result)+Environment.NewLine);}}
  });File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"recording-test.txt"),"OK "+directory);}catch(Exception ex){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"recording-test.txt"),"FAIL "+ex);Environment.ExitCode=1;}finally{fixture.Close();}};fixture.ShowDialog();}}
 }
}
